214	/** Iterate decoded children without constructing a sibling value/task array. */
215	function* losslessChildren(
216	  value: readonly LosslessJsonValue[] | { readonly [key: string]: LosslessJsonValue },
217	): Generator<LosslessJsonValue> {
218	  if (Array.isArray(value)) {
219	    yield* value;
220	    return;
221	  }
222	  for (const key in value) {
223	    const child = (value as { readonly [key: string]: LosslessJsonValue })[key];
224	    if (child === undefined) refuse("internal");
225	    yield child;
226	  }
227	}
228	function boundLossless(root: LosslessJsonValue): void {
229	  const frames: { children: Iterator<LosslessJsonValue>; depth: number }[] = [];
230	  let nodes = 0;
231	  const discover = (value: LosslessJsonValue, depth: number): void => {
232	    // Charge each discovered value before scheduling any of its children.
233	    if (++nodes > 100000 || depth > 16) refuse("bounds");
234	    if (value !== null && typeof value === "object" && !(value instanceof JsonNumberLiteral))
235	      frames.push({ children: losslessChildren(value), depth });
236	  };
237	  discover(root, 0);
238	  for (let frame = frames.at(-1); frame !== undefined; frame = frames.at(-1)) {
239	    const child = frame.children.next();
240	    if (child.done) frames.pop();
241	    else discover(child.value, frame.depth + 1);
242	  }
243	}
244	function immutable<T>(value: T): T {
245	  if (value !== null && typeof value === "object") {
246	    for (const child of Object.values(value)) immutable(child);
247	    Object.freeze(value);
248	  }
249	  return value;
250	}
251	/** The byte ceiling is the sole predecode bound. The strict decoder allocates
252	 * its lossless tree before the iterative depth/node checks below. Trusted local
253	 * input accepts that bounded-byte allocation/work risk. */
254	export async function loadReferenceDeployment(
255	  input: ReferenceDeploymentInput,
256	): Promise<PreparedReferenceDeployment> {
257	  let phase: ReferenceDeploymentErrorCode = "configuration";
258	  try {
259	    const startup = snapshot(input);
260	    phase = "file";
261	    const bytes = await readDeployment(startup.deploymentFile);
262	    phase = "syntax";
263	    // Keep BOM visible to the existing strict JSON decoder.
264	    const lossless = decodeJsonDocument(
265	      new TextDecoder("utf-8", { fatal: true, ignoreBOM: true }).decode(bytes),
266	    );
267	    boundLossless(lossless);
268	    const admitted = admitJsonNumbers(lossless, {
269	      diagnostics: 1,
270	      diagnostic: () => ({ message: "unsupported reference deployment number" }),
271	    });
272	    if (!admitted.ok) refuse("syntax");
273	    phase = "contract";
274	    const envelope = administrativeData(admitted.value, ["format", "profile", "configuration"]);
275	    if (
276	      envelope.format !== "bdptest-reference-deployment-1" ||
277	      envelope.profile !== startup.profile
278	    )
279	      refuse("contract");
280	    const fileDigest = createHash("sha256").update(bytes).digest("hex");
281	    const summary = {
282	      format: "bdptest-reference-deployment-1" as const,
283	      canonicalScope: startup.canonicalScope,
284	      listener: startup.listener,
285	      preflightReadLimits: startup.limits,
286	      fileDigest,
287	    };
288	    if (startup.profile === "read-update") {
289	      const configuration = administrativeData(envelope.configuration, [
290	        "directory",
291	        "create",
292	        "credentials",
293	        "policies",
294	        "contracts",
295	        "maximumEndpointMultiplicity",
296	      ]);
297	      const projectedInput = immutable({
298	        scope: startup.canonicalScope,
299	        listener: startup.listener,
300	        ...configuration,
301	      });
302	      const installed = captureInstalledReferenceConfiguration(projectedInput);
303	      const handle: PreparedReadUpdateDeployment = Object.freeze({
304	        ...summary,
305	        profile: "read-update",
306	        artifactIdentity: installed.artifactIdentity,
307	        configurationIdentity: installed.identity,
308	        policyIdentity: installed.policyIdentity,
309	        authenticationIdentity: installed.authenticationIdentity,
310	      });
311	      phase = "internal";
312	      registerReferenceDeployment(handle, { profile: "read-update", projectedInput, installed });
313	      return handle;
314	    }
315	    const configuration = administrativeData(envelope.configuration, [
316	      "directory",
317	      "create",
318	      "credentials",
319	      "artifacts",
320	    ]);
321	    const projectedInput = immutable({ scope: startup.canonicalScope, ...configuration });
322	    const installed = captureInstalledTransactionConfiguration(projectedInput);
323	    const preflight = captureTransactionRuntimeConfiguration(installed);
324	    if (
325	      preflight.contracts === undefined ||
326	      preflight.authorityMode !== "canonical" ||
327	      preflight.configuredScope !== startup.canonicalScope ||
328	      Object.keys(preflight.seams).length !== 0 ||
329	      !preflight.liveStreamsAvailable ||
330	      preflight.settings.changefeedStream.heartbeatMilliseconds >=
331	        preflight.settings.transport.timeout ||
332	      !isDeepStrictEqual(
333	        preflight.readOptions(startup.canonicalScope).advertisedLimits,
334	        startup.limits,
335	      )
336	    )
337	      refuse("contract");
338	    const handle: PreparedTransactionalDeployment = Object.freeze({
339	      ...summary,
340	      profile: "transactional",
341	      artifactIdentity: preflight.contracts.identity,
342	    });
343	    phase = "internal";
344	    registerReferenceDeployment(handle, {
345	      profile: "transactional",
346	      projectedInput,
347	      installed,
348	      preflight,
349	    });
350	    return handle;
351	  } catch (error) {
352	    if (error instanceof ReferenceDeploymentError) throw error;
353	    // Neither causes nor parser/filesystem/compiler details cross this local boundary.
354	    throw new ReferenceDeploymentError(phase);
355	  }
356	}
