719	        ownerFacts: checkedOwner,
720	      });
721	    }
722	    serving = true;
723	    published = true;
724	  } catch (error) {
725	    prepared?.signal?.removeEventListener("abort", onAbort);
726	    terminal.reject(error);
727	    const cleanup = prepared
728	      ? [
729	          ...(await Promise.allSettled([closeListener()])),
730	          ...(await Promise.allSettled([...pending])),
731	          ...(await Promise.allSettled(authority === undefined ? [] : [authority.close()])),
732	        ]
733	      : await Promise.allSettled([
734	          ...(server.listening ? [closeListener()] : []),
735	          ...(authority === undefined ? [] : [authority.close()]),
736	        ]);
737	    const failures = [
738	      ...listenerFaults.filter((fault) => fault !== error),
739	      ...cleanup.flatMap((result) => (result.status === "rejected" ? [result.reason] : [])),
740	    ];
741	    if (failures.length)
742	      throw new AggregateError([error, ...failures], "installed startup cleanup failed", {
743	        cause: error,
744	      });
745	    throw error;
746	  }
747	  let completion: Promise<void> | undefined;
748	  // The owner has a terminal close result. Retry listener cleanup only; never
749	  // re-invoke owner close or erase its original failure.
750	  let ownerCompletion: Promise<void> | undefined;
751	  function close(): Promise<void> {
752	    if (!completion) {
753	      closing = true;
754	      serving = false;
755	      completion = (async () => {
756	        const listener = await Promise.allSettled([closeListener()]);
757	        await Promise.allSettled([...pending]);
758	        ownerCompletion ??= Promise.resolve().then(() => authority?.close());
759	        const owner = await Promise.allSettled([ownerCompletion]);
760	        const failures = [...listener, ...owner].flatMap((result) =>
761	          result.status === "rejected" ? [result.reason] : [],
762	        );
763	        failures.unshift(...listenerFaults);
764	        if (failures.length)
765	          throw new AggregateError(failures, "installed shutdown cleanup failed");
766	      })()
767	        .then(
768	          () => {
769	            terminal.resolve();
770	          },
771	          (error: unknown) => {
772	            terminal.reject(error);
773	            if (!prepared) completion = undefined;
774	            throw error;
775	          },
776	        )
777	        .finally(() => {
778	          prepared?.signal?.removeEventListener("abort", onAbort);
779	        });
780	      void completion.catch(() => {});
781	    }
782	    return completion;
783	  }
784	  const legacy = { scope, close };
785	  if (!prepared) return Object.freeze(legacy);
786	  return Object.freeze({
787	    ...legacy,
788	    listenUrl: preparedFacts!.listenUrl,
789	    history: preparedFacts!.history,
790	    completion: terminal.promise,
791	    ownerFacts: preparedFacts!.ownerFacts,
792	  });
793	}
