1	/** Private installed reference candidate configuration. No profile admission. */
2	import { createHash } from "node:crypto";
3	import path from "node:path";
4	import {
5	  parseCanonicalScope,
6	  REFERENCE_TYPE_DESCRIPTORS,
7	  stringifyJsonValue,
8	  type TypeDescriptor,
9	} from "@bdp/protocol";
10	import { CONTRACT_ARTIFACT_CEILINGS } from "./installed-contract-artifact.js";
11	import {
12	  administrativeArray,
13	  administrativeData,
14	  compileDevelopmentContracts,
15	  captureDevelopmentAggregatePolicy,
16	  createDevelopmentAccessPolicy,
17	  type DevelopmentAccess,
18	} from "./development-contracts.js";
19	import { DEVELOPMENT_OWNER_LIMITS } from "./development-authority.js";
20	
21	/** Reference identities are instantiated locally; the work.example identities
22	 * are not hosted or claimed. Remap every Type-reference position together. */
23	export function referenceTypeArtifacts(scope: string) {
24	  const canonical = parseCanonicalScope(scope);
25	  const ids = new Map(
26	    REFERENCE_TYPE_DESCRIPTORS.map((d) => [
27	      d.id,
28	      `${canonical}types/${new URL(d.id).pathname.split("/").at(-1)}`,
29	    ]),
30	  );
31	  const remap = (id: string) => {
32	    const mapped = ids.get(id);
33	    if (mapped === undefined) throw new TypeError("reference closure is incomplete");
