  expect(id).toBe(client.scope + "beads/startup");
  expect(
    isDeepStrictEqual(JSON.parse((await client.send("read", "GET", id, 200)).bodyText), resource),
  ).toBe(true);
  const replay = await client.send(
    "replay",
    "POST",
    routes.createTarget,
    200,
    "writer",
    payload(client),
    "startup-created",
  );
  expect(replay.bodyText).toBe(created.bodyText);
