        return actual.createReadRoute(...values);
      },
    };
    return actualComposition;
  });
  vi.spyOn(authority, "openDevelopmentAuthority").mockImplementation(async (...args) => {
    trace.push("open-RU");
    const owner = await openRU(...args);
    returned++;
